mkdir -p /app/bin /app/out; cat > /app/bin/crosstabs.py <<'EOF'
#!/usr/bin/env python3
import csv, io, json, os, sys
from datetime import datetime, timedelta, timezone


def read_exports(d):
    rows = []
    ed = os.path.join(d, "exports")
    names = sorted(n for n in os.listdir(ed)
                   if n.endswith(".csv") and os.path.isfile(os.path.join(ed, n)))
    for n in names:
        with open(os.path.join(ed, n), "rb") as f:
            text = f.read().decode("utf-8-sig")
        first = text.replace("\r\n", "\n").split("\n", 1)[0]
        delim = next((c for c in (",", ";", "\t") if c in first), ",")
        rd = csv.reader(io.StringIO(text, newline=""), delimiter=delim)
        header = None
        for rec in rd:
            if header is None:
                header = [h.strip() for h in rec]
                continue
            cells = [c.strip() for c in rec]
            if not any(cells):
                continue
            row = {}
            for h, c in zip(header, cells):
                row[h] = c if c != "" else None
            rows.append(row)
    return rows


def parse_offset(s):
    sign = -1 if s[0] == "-" else 1
    h, m = s[1:].split(":")
    return timezone(sign * timedelta(hours=int(h), minutes=int(m)))


def parse_time(s, meta):
    if meta["submitted_format"] == "local":
        dt = datetime.strptime(s, "%Y-%m-%d %H:%M:%S")
        return dt.replace(tzinfo=parse_offset(meta["utc_offset"]))
    if s.endswith("Z"):
        s = s[:-1] + "+00:00"
    return datetime.fromisoformat(s)


def parse_dur(s, fmt):
    if fmt == "clock":
        t = 0
        for p in s.split(":"):
            t = t * 60 + int(p)
        return t
    return int(s)


def median(v):
    v = sorted(v)
    n = len(v)
    if n % 2:
        return v[n // 2]
    return (v[n // 2 - 1] + v[n // 2]) / 2


def rnd(x):
    return None if x is None else round(x + 0.0, 2)


def main():
    ind, outf = sys.argv[1], sys.argv[2]
    cb = json.load(open(os.path.join(ind, "codebook.json"), encoding="utf-8"))
    wt = json.load(open(os.path.join(ind, "weighting.json"), encoding="utf-8"))
    plan = json.load(open(os.path.join(ind, "tables.json"), encoding="utf-8"))
    vkeys = list(cb["versions"].keys())
    stats = {k: dict(rows=0, duplicates=0, short_partials=0, speeders=0, complete=0, partial=0) for k in vkeys}

    recs = []
    for r in read_exports(ind):
        v = r.get("form_version")
        if v not in cb["versions"]:
            continue
        m = cb["versions"][v]["meta"]
        rid = r.get(m["id"])
        complete = r.get(m["status"]) == m["complete"]
        t = parse_time(r[m["submitted"]], m) if r.get(m["submitted"]) else None
        lp = r.get(m["last_page"])
        lp = int(lp) if lp is not None else 0
        dur = r.get(m["duration"])
        dur = parse_dur(dur, m["duration_format"]) if dur is not None else None
        stats[v]["rows"] += 1
        recs.append(dict(v=v, id=rid, complete=complete, t=t, lp=lp, dur=dur, row=r))

    # duplicates
    by = {}
    for x in recs:
        by.setdefault(x["id"], []).append(x)
    kept = []
    epoch = datetime(1970, 1, 1, tzinfo=timezone.utc)
    for rid, g in by.items():
        best = max(g, key=lambda x: (x["complete"], (x["t"] - epoch) if x["t"] else timedelta(days=-10**6)))
        for x in g:
            if x is not best:
                stats[x["v"]]["duplicates"] += 1
        kept.append(best)
    # short partials
    k2 = []
    for x in kept:
        if not x["complete"] and x["lp"] < cb["partial_min_page"]:
            stats[x["v"]]["short_partials"] += 1
        else:
            k2.append(x)
    # speeders
    med = {}
    for v in vkeys:
        d = [x["dur"] for x in k2 if x["v"] == v and x["complete"]]
        if d:
            med[v] = median(d)
    k3 = []
    for x in k2:
        if x["complete"] and x["dur"] * 5 < med[x["v"]] * 2:
            stats[x["v"]]["speeders"] += 1
        else:
            k3.append(x)
    for x in k3:
        stats[x["v"]]["complete" if x["complete"] else "partial"] += 1

    # answers
    questions = cb["questions"]
    qmap = {q["id"]: q for q in questions}

    def to_code(val, ent):
        rc = ent.get("recode")
        if rc is not None:
            return int(rc[val])
        return int(val)

    def read(q, x):
        ent = q["versions"][x["v"]]
        r = x["row"]
        t = q["type"]
        if t == "single":
            val = r.get(ent["column"])
            if val is None:
                return None
            c = to_code(val, ent)
            miss = {o["code"] for o in q["options"] if o.get("missing")}
            return None if c in miss else c
        if t == "age":
            val = r.get(ent["column"])
            if val is None:
                return None
            src = ent.get("source")
            if src == "band":
                c = to_code(val, ent)
                return c
            age = int(val)
            if src == "birth_year":
                age = int(cb["reference_date"][:4]) - age
            for b in q["bands"]:
                if b["min"] <= age <= b["max"]:
                    return b["code"]
            return None
        chosen = set()
        if "columns" in ent:
            for code, col in ent["columns"].items():
                if r.get(col) == "1":
                    chosen.add(int(code))
        else:
            val = r.get(ent["column"])
            if val is not None:
                for e in val.split(ent["separator"]):
                    e = e.strip()
                    if e:
                        chosen.add(to_code(e, ent))
        excl = {o["code"] for o in q["options"] if o.get("exclusive")}
        miss = {o["code"] for o in q["options"] if o.get("missing")}
        if chosen - excl:
            chosen -= excl
        elif chosen:
            return None
        chosen -= miss
        return chosen or None

    for x in k3:
        ans = {}
        for q in questions:
            v = x["v"]
            ent = q["versions"].get(v)
            if ent is None:
                continue
            if not x["complete"] and ent["page"] > x["lp"]:
                continue
            ai = q.get("ask_if")
            if ai:
                a = ans.get(ai["question"])
                if a is None:
                    continue
                codes = set(ai["codes"])
                ok = bool(a & codes) if isinstance(a, set) else a in codes
                if not ok:
                    continue
            a = read(q, x)
            ans[q["id"]] = a if a is not None else None
            if a is None:
                ans.pop(q["id"])
                ans.setdefault("_asked", set()).add(q["id"])
            else:
                ans.setdefault("_asked", set()).add(q["id"])
        x["ans"] = ans

    n = len(k3)
    # weighting
    w = [1.0] * n
    if n:
        dims = []
        for d in wt["dimensions"]:
            q = d["question"]
            cats = [x["ans"].get(q) for x in k3]
            present = {c for c in cats if c is not None}
            tg = {int(k): float(v) for k, v in d["targets"].items() if int(k) in present}
            s = sum(tg.values())
            if not tg or s == 0:
                continue
            tg = {k: v / s for k, v in tg.items()}
            idx = {c: [i for i, cc in enumerate(cats) if cc == c] for c in tg}
            dims.append((tg, idx))
        for _ in range(wt["max_iterations"]):
            ok = True
            for tg, idx in dims:
                T = sum(w[i] for l in idx.values() for i in l)
                for c, l in idx.items():
                    W = sum(w[i] for i in l)
                    f = tg[c] * T / W
                    if abs(f - 1) > wt["tolerance"]:
                        ok = False
                    for i in l:
                        w[i] *= f
            if ok:
                break
        m = sum(w) / n
        hi, lo = wt["cap"] * m, wt["floor"] * m
        w = [min(max(a, lo), hi) for a in w]
        m2 = sum(w) / n
        w = [a / m2 for a in w]

    summary = {"versions": [dict(version=k, **stats[k]) for k in vkeys], "respondents": n}
    if n:
        summary["effective_n"] = rnd(sum(w) ** 2 / sum(a * a for a in w))
        summary["weight_min"] = rnd(min(w))
        summary["weight_max"] = rnd(max(w))
    else:
        summary["effective_n"] = summary["weight_min"] = summary["weight_max"] = None

    def opts(q):
        src = q["bands"] if q["type"] == "age" else q["options"]
        return [o for o in src if not o.get("missing")]

    cols = [("total", None, None)]
    for b in plan["banner"]:
        for o in opts(qmap[b]):
            cols.append((f"{b}:{o['code']}", b, o["code"]))

    tables = []
    for t in plan["tables"]:
        q = qmap[t["question"]]
        multi = q["type"] == "multi"
        base_idx = [i for i, x in enumerate(k3) if x["ans"].get(q["id"]) is not None]
        rows = [(str(o["code"]), {o["code"]}) for o in opts(q)]
        for nt in t.get("nets", []):
            rows.append((nt["id"], set(nt["codes"])))

        def has(i, codes):
            a = k3[i]["ans"][q["id"]]
            return bool(a & codes) if multi else a in codes
        outc = []
        for cid, bq, bc in cols:
            idx = [i for i in base_idx if bq is None or k3[i]["ans"].get(bq) == bc]
            wb = sum(w[i] for i in idx)
            vals = {}
            if not idx:
                for k, _ in rows:
                    vals[k] = None
                if t.get("mean"):
                    vals["mean"] = None
                outc.append({"column": cid, "base": 0, "weighted_base": 0, "values": vals})
                continue
            for k, codes in rows:
                vals[k] = rnd(100 * sum(w[i] for i in idx if has(i, codes)) / wb)
            if t.get("mean"):
                sc = {o["code"]: o["score"] for o in opts(q)}
                vals["mean"] = rnd(sum(w[i] * sc[k3[i]["ans"][q["id"]]] for i in idx) / wb)
            outc.append({"column": cid, "base": len(idx), "weighted_base": rnd(wb), "values": vals})
        tables.append({"table": t["id"], "columns": outc})

    with open(outf, "w", encoding="utf-8") as f:
        json.dump({"survey": cb["survey"], "summary": summary, "tables": tables}, f, indent=1)


main()
